import json,sys,collections
for n in sys.argv[1:]:
    g=json.load(open(f'.corpora/work/{n}.gap.json'))
    print('=====',n)
    mp=[p for p in g['missing_props'] if p['kind']=='own']
    print('own missing',len(mp),'react missing',len(g['missing_props'])-len(mp))
    c=collections.Counter((p['file'],p['name']) for p in mp)
    print('top own-missing components'); 
    for k,v in c.most_common(25): print(' ',v,k)
    c=collections.Counter(p['parent'][:70] for p in mp)
    print('by parent'); 
    for k,v in c.most_common(15): print(' ',v,k)
    print('missing comps by nprops (own total):', sum(x['nprops'] for x in g['missing_components']))
    for x in sorted(g['missing_components'],key=lambda x:-x['nprops'])[:30]: print(' ',x['nprops'],x['file'],x['name'],x['caliper_in_file'][:4])
EOF
